"""IBM Bob adapter. Output is backwards compatible with v0.4 Bob installs."""

from __future__ import annotations

from .. import bobsetup
from .base import (
    Adapter, Check, SettingsError, SetupContext, dump_settings,
    load_settings, merge_hook_entries, plan_block, plan_managed_file,
    plan_remove_block, plan_remove_managed_file, remove_hook_entries,
)
from .claude import claude_reads_agents_md

# Strings that identify files written by repo-ai v0.4 (before ownership markers).
_V04_SIGNATURES = {
    "skill": "Generated by `repo-ai`",
    "rules": "generated context layer",
    "command": "repo-ai",
    "persona": "repo-ai context",
    "hook": "# repo-ai ::",
}


def _agents_block_shared(ctx: SetupContext) -> bool:
    """Claude also reads AGENTS.md (CLAUDE.md imports it) and Claude is active."""
    return claude_reads_agents_md(ctx)


class BobAdapter(Adapter):
    name = "bob"

    def _bob_dir(self, ctx: SetupContext):
        return ctx.root / ".bob"

    def plan_install(self, ctx: SetupContext) -> None:
        facts = ctx.facts
        assert facts is not None
        rel = ctx.layout.context_rel
        bob = self._bob_dir(ctx)
        cfg = ctx.cfg
        plan = ctx.plan

        if cfg.write_agents_md:
            block = bobsetup.build_agents_block(facts, rel, shared_with_claude=_agents_block_shared(ctx))
            plan_block(plan, ctx.root / "AGENTS.md", bobsetup.BEGIN, bobsetup.END, block,
                       create_with=f"# {ctx.root.name}\n\n")
        if cfg.write_skill:
            plan_managed_file(plan, bob / "skills" / bobsetup.SKILL_NAME / "SKILL.md",
                              bobsetup.build_skill(facts, rel), "bob-skill",
                              legacy_signature=_V04_SIGNATURES["skill"])
            plan_managed_file(plan, bob / "rules" / "00-repo-ai.md",
                              bobsetup.rules_pointer(rel), "bob-rule",
                              legacy_signature=_V04_SIGNATURES["rules"])
            for name, body in bobsetup.commands(rel).items():
                plan_managed_file(plan, bob / "commands" / name, body, "bob-command",
                                  legacy_signature=_V04_SIGNATURES["command"])
            plan_managed_file(plan, bob / "agents" / "repo-explorer.md",
                              bobsetup.explorer_persona(rel), "bob-agent",
                              legacy_signature=_V04_SIGNATURES["persona"])
        if cfg.write_hooks:
            for name, body in bobsetup.hook_scripts(ctx.layout.state_rel).items():
                plan_managed_file(plan, bob / "hooks" / name, body, "bob-hook",
                                  legacy_signature=_V04_SIGNATURES["hook"],
                                  executable=True, comment="hash")
            settings_path = bob / "settings.json"
            try:
                data = load_settings(plan.current(settings_path))
                merged = merge_hook_entries(data, bobsetup.hooks_config(),
                                            bobsetup.is_repo_ai_bob_hook)
                plan.write_shared(settings_path, dump_settings(merged, plan.current(settings_path)))
            except SettingsError as exc:
                plan.skip(settings_path, f"{exc}; fix it and re-run — not overwritten")
        if cfg.write_bobignore:
            internal = ctx.layout.runtime_ignore_entries()
            plan_block(plan, ctx.root / ".bobignore", bobsetup.BOBIGNORE_HEADER,
                       bobsetup.BOBIGNORE_FOOTER,
                       bobsetup.bobignore_block(ctx.quarantined, internal))

    def plan_uninstall(self, ctx: SetupContext) -> None:
        plan = ctx.plan
        bob = self._bob_dir(ctx)
        root_name = ctx.root.name
        plan_remove_block(plan, ctx.root / "AGENTS.md", bobsetup.BEGIN, bobsetup.END,
                          delete_if=lambda rest: rest.strip() in {"", f"# {root_name}"})
        plan_remove_block(plan, ctx.root / ".bobignore", bobsetup.BOBIGNORE_HEADER,
                          bobsetup.BOBIGNORE_FOOTER, delete_if=lambda rest: not rest.strip())
        plan_remove_managed_file(plan, bob / "skills" / bobsetup.SKILL_NAME / "SKILL.md",
                                 _V04_SIGNATURES["skill"])
        plan_remove_managed_file(plan, bob / "rules" / "00-repo-ai.md", _V04_SIGNATURES["rules"])
        for name in bobsetup.COMMAND_NAMES:
            plan_remove_managed_file(plan, bob / "commands" / name, _V04_SIGNATURES["command"])
        plan_remove_managed_file(plan, bob / "agents" / "repo-explorer.md", _V04_SIGNATURES["persona"])
        for name in bobsetup.hook_scripts(ctx.layout.state_rel):
            plan_remove_managed_file(plan, bob / "hooks" / name, _V04_SIGNATURES["hook"])
        settings_path = bob / "settings.json"
        current = plan.current(settings_path)
        if current is not None:
            try:
                data = remove_hook_entries(load_settings(current), bobsetup.is_repo_ai_bob_hook)
                if data:
                    plan.write_shared(settings_path, dump_settings(data, current))
                else:
                    plan.delete(settings_path, shared=True)
                    plan.remove_dir_if_empty(bob)
            except SettingsError as exc:
                plan.skip(settings_path, f"{exc}; repo-ai hooks not removed")

    def doctor(self, ctx: SetupContext) -> list[Check]:
        checks: list[Check] = []
        bob = self._bob_dir(ctx)
        agents_md = ctx.root / "AGENTS.md"
        text = agents_md.read_text("utf-8", errors="replace") if agents_md.is_file() else ""
        checks.append(Check("AGENTS.md repo-ai block", "ok" if bobsetup.BEGIN in text else "fail",
                            "" if bobsetup.BEGIN in text else "missing", "repo-ai update"))
        if text:
            tokens = len(text) // 4
            checks.append(Check("AGENTS.md size", "ok" if tokens < 1200 else "warn",
                                f"~{tokens} tokens loaded on every Bob prompt"))
        for label, path in (("Bob skill", bob / "skills" / bobsetup.SKILL_NAME / "SKILL.md"),
                            ("Bob prompt hook", bob / "hooks" / "user-prompt.sh"),
                            (".bobignore", ctx.root / ".bobignore")):
            checks.append(Check(label, "ok" if path.is_file() else "fail",
                                path.relative_to(ctx.root).as_posix(), "repo-ai update"))
        settings = bob / "settings.json"
        if settings.is_file():
            try:
                data = load_settings(settings.read_text("utf-8"))
                registered = any(bobsetup.is_repo_ai_bob_hook(e)
                                 for e in (data.get("hooks") or {}).get("UserPromptSubmit", []))
                checks.append(Check("Bob hooks registered", "ok" if registered else "fail",
                                    ".bob/settings.json", "repo-ai update"))
            except SettingsError as exc:
                checks.append(Check(".bob/settings.json", "fail", str(exc), "fix the JSON by hand"))
        else:
            checks.append(Check("Bob hooks registered", "fail", "no .bob/settings.json", "repo-ai update"))
        return checks
